  const [loading, setLoading] = useState(false);
  const [aiInsight, setAiInsight] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'passes' | 'directory' | 'profile'>('passes');
  const [searchTerm, setSearchTerm] = useState('');
  const [isScanning, setIsScanning] = useState(false);
  const [validatedPass, setValidatedPass] = useState<IssuedPass | null>(null);
  const [countdown, setCountdown] = useState(60);

  useEffect(() => { 
    refreshData(); 
    const timer = setInterval(refreshData, 30000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    let timer: number;
    if (validatedPass && countdown > 0) {
      timer = window.setInterval(() => setCountdown(prev => prev - 1), 1000);
    } else if (countdown === 0) {
      setValidatedPass(null);
      setCountdown(60);
    }
    return () => clearInterval(timer);
  }, [validatedPass, countdown]);

  const refreshData = async () => {
    const h = await storageService.getHospitals();
    const apprvs = await storageService.getApprovals();
    const allApps = await storageService.getApplications();
    const a = allApps.filter(ap => ap.mrId === user.id);
    const allPasses = await storageService.getPasses();
    const p = allPasses.filter(ps => ps.mrId === user.id);
    setHospitals(h); setApprovals(apprvs); setApps(a); setPasses(p);

    // Using Python AI Service instead of Gemini
    const insight = await getPriorityInsights(a.slice(-3).map(app => ({ date: app.applicationDate, status: app.status })), user.fullName);
    setAiInsight(insight);
  };

  const handleScanDetected = async (qrValueInput?: string) => {
    const latestPasses = await storageService.getPasses();
    const today = new Date().toLocaleDateString('en-CA');
    let qrValue = qrValueInput || prompt("Enter Unique Hospital Gate ID (e.g. MEDPASS-GATE-h1):");

    if (!qrValue?.startsWith('MEDPASS-GATE-')) {
      showFeedback("Invalid Gate QR format.", "error");
      return;
    }

    const hospitalIdFromQR = qrValue.replace('MEDPASS-GATE-', '');
    const myPassesToday = latestPasses.filter(p => p.mrId === user.id && p.passDate === today && p.entryStatus === 'not_entered');
    const myEligiblePasses = myPassesToday.filter(p => p.hospitalId === hospitalIdFromQR);

    if (myEligiblePasses.length === 0) {
      if (myPassesToday.length > 0) {
        showFeedback("Wrong Gate: This pass belongs to another hospital. Try with the relevant hospital gate.", "error");
      } else {
        showFeedback("No valid entry pass found for today at this hospital.", "error");
      }
      return;
    }

    const activePass = myEligiblePasses.find(p => getScanStatus(p.session).open);

    if (!activePass) {
      const status = getScanStatus(myEligiblePasses[0].session);
      showFeedback(`Scan Failed: ${status.message}`, "error");
      return;
    }

    const updatedPasses = latestPasses.map(p => p.id === activePass.id ? { ...p, entryStatus: 'entered' as const } : p);
    const log = { 
      id: Math.random().toString(36).substr(2, 9), 
      issuedPassId: activePass.id, 
      entryTime: new Date().toISOString(), 
      verifiedBy: 'Self-Gate-Scanner' 
    };

    await storageService.savePasses(updatedPasses);
    const currentLogs = await storageService.getLogs();
    await storageService.saveLogs([...currentLogs, log]);

    setIsScanning(false);
    setValidatedPass(activePass);
    setCountdown(60);
    refreshData();
    showFeedback(`Access approved for ${activePass.session} session!`, 'success');
  };

  const isSessionWindowOpen = (h: Hospital, session: SessionType) => {
    const window = h.sessionWindows?.[session];
    if (!window) return false;
    const now = new Date();
    const time = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
    return time >= window.start && time <= window.end;
  };

  const handleApply = async (hospitalId: string, session: SessionType) => {
    setLoading(true);
    const todayStr = new Date().toLocaleDateString('en-CA');
    const newApp: PassApplication = {
      id: Math.random().toString(36).substr(2, 9), mrId: user.id, hospitalId, session,
      applicationDate: todayStr, priorityScore: 0, status: 'applied', createdAt: new Date().toISOString()
    };
    const currentApps = await storageService.getApplications();
    await storageService.saveApplications([...currentApps, newApp]);
    setTimeout(() => { refreshData(); setLoading(false); showFeedback("Application submitted!"); }, 600);
  };

  const todayStr = new Date().toLocaleDateString('en-CA');
  const activePassesToday = passes.filter(p => p.entryStatus === 'not_entered' && p.passDate === todayStr);
  const currentlyVisiting = passes.filter(p => p.entryStatus === 'entered' && p.passDate === todayStr);

  return (
    <div className="space-y-6">
      {validatedPass && (
        <div className="fixed inset-0 z-[110] bg-green-600 flex flex-col items-center justify-center p-8 animate-in zoom-in duration-300">
          <div className="w-full max-w-sm text-center">
            <div className="bg-white/20 w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-8 animate-pulse"><CheckCircle2 className="h-16 w-16 text-white" /></div>
            <h2 className="text-4xl font-black text-white mb-2 tracking-tighter uppercase">Gate Open</h2>
            <p className="text-green-100 font-bold uppercase tracking-widest text-[10px] mb-12">Validation Successful • Proceed Now</p>
            <div className="bg-white/10 rounded-[2.5rem] p-10 backdrop-blur-md border border-white/20 shadow-2xl">
              <p className="text-white/60 text-xs font-black uppercase tracking-widest mb-2">Gate Timer</p>
              <div className="text-8xl font-black text-white tabular-nums tracking-tighter">{countdown}</div>
              <p className="text-white/80 text-sm font-bold mt-4">Seconds to enter</p>
            </div>
            <button onClick={() => setValidatedPass(null)} className="mt-12 px-8 py-4 bg-white text-green-700 rounded-2xl font-black text-xs uppercase shadow-xl active:scale-95 transition-all">Dismiss</button>
          </div>
        </div>
      )}

      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('passes')} className={`px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'passes' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><QrCode className="h-4 w-4" /> My Passes</button>
        <button onClick={() => setActiveTab('directory')} className={`px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'directory' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Building2 className="h-4 w-4" /> Directory</button>
        <button onClick={() => setActiveTab('profile')} className={`px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'profile' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><UserCircle className="h-4 w-4" /> Profile</button>
      </div>

      {activeTab !== 'profile' && (
        <div className="bg-indigo-50 border border-indigo-100 p-4 rounded-xl flex items-start gap-3 shadow-sm animate-in slide-in-from-top-2">
          <Zap className="h-5 w-5 text-indigo-500 mt-0.5" />
          <p className="text-sm text-indigo-800 leading-relaxed font-medium">
            <span className="font-black uppercase text-[10px] bg-indigo-200 text-indigo-700 px-1.5 py-0.5 rounded mr-2">Python Insight Engine</span>
            {aiInsight || "Calculating your priority standing..."}
          </p>
        </div>
      )}

      {activeTab === 'passes' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <section className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 lg:col-span-2">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-lg font-bold flex items-center gap-2"><Building2 className="h-5 w-5 text-indigo-500" /> Authorized Facilities</h3>
              <div className="bg-slate-50 px-3 py-1.5 rounded-xl border border-slate-200">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Apply Period</p>
              </div>
            </div>
            <div className="grid gap-6 sm:grid-cols-2">
              {hospitals.filter(h => approvals.some(a => a.mrId === user.id && a.hospitalId === h.id && a.status === 'approved')).map(h => (
                <div key={h.id} className="p-5 bg-slate-50 rounded-2xl border border-slate-100 hover:shadow-md transition-all group">
                  <p className="font-bold text-slate-800 text-lg mb-4 group-hover:text-indigo-600 transition-colors">{h.name}</p>
                  <div className="space-y-3">
                    {h.supportedSessions.map(sess => {
                      const open = isSessionWindowOpen(h, sess);
                      const window = h.sessionWindows?.[sess];
                      return (
                        <div key={sess} className="space-y-1">
                          <button 
                            disabled={!open || loading} 
                            onClick={() => handleApply(h.id, sess)} 
                            className={`w-full py-3 px-4 rounded-xl text-xs font-black flex items-center justify-between transition-all ${open ? 'bg-white border-2 border-indigo-100 hover:border-indigo-400 text-indigo-700 shadow-sm active:scale-95' : 'bg-slate-200 text-slate-400 grayscale cursor-not-allowed'}`}
                          >
                            <span className="flex items-center gap-2">{sess === 'MORNING' ? <Sun className="h-4 w-4" /> : sess === 'EVENING' ? <Moon className="h-4 w-4" /> : <Maximize className="h-4 w-4" />}{sess}</span>
                            <span className="flex items-center gap-1">{open ? 'APPLY NOW' : 'CLOSED'}</span>
                          </button>
                          <div className="px-2 flex justify-between items-center text-[9px] font-bold text-slate-400 uppercase tracking-tighter">
                            <span>Applying Window:</span>
                            <span>{window?.start} - {window?.end}</span>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}
              {hospitals.filter(h => approvals.some(a => a.mrId === user.id && a.hospitalId === h.id && a.status === 'approved')).length === 0 && (
                <div className="sm:col-span-2 p-12 text-center bg-slate-50 border-2 border-dashed border-slate-200 rounded-3xl">
                  <Building2 className="h-8 w-8 text-slate-300 mx-auto mb-4 opacity-20" />
                  <p className="text-sm font-bold text-slate-400">No facilities approved yet. Please request access from the directory.</p>
                </div>
              )}
            </div>
          </section>

          <section className="space-y-6">
            {currentlyVisiting.length > 0 && (
              <div className="bg-green-600 p-6 rounded-3xl shadow-xl shadow-green-100 border border-green-500 animate-in slide-in-from-right-4">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="text-sm font-black text-white uppercase tracking-widest flex items-center gap-2"><ShieldCheck className="h-4 w-4" /> Visiting Now</h3>
                  <div className="bg-white/20 px-2 py-1 rounded-lg"><span className="text-[10px] font-black text-white uppercase">Active</span></div>
                </div>
                {currentlyVisiting.map(p => (
                  <div key={p.id} className="space-y-4">
                    <p className="font-black text-white text-lg leading-tight">{hospitals.find(h => h.id === p.hospitalId)?.name}</p>
                    <div className="bg-white/10 p-4 rounded-2xl border border-white/10 text-white">
                      <div className="flex justify-between items-center"><p className="text-[10px] font-black uppercase opacity-60">Session</p><p className="text-xs font-black">{p.session}</p></div>
                      <div className="flex justify-between items-center mt-2 border-t border-white/10 pt-2"><p className="text-[10px] font-black uppercase opacity-60">Pass Expiry Time</p><p className="text-xs font-black">{getExpiryTimeLabel(p.session)}</p></div>
                    </div>
                  </div>
                ))}
              </div>
            )}

            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-lg font-bold flex items-center gap-2"><QrCode className="h-5 w-5 text-indigo-500" /> My Active Passes</h3>
                {activePassesToday.some(p => getScanStatus(p.session).open) && (
                  <button onClick={() => setIsScanning(true)} className="flex items-center gap-1.5 bg-indigo-600 text-white px-3 py-1.5 rounded-xl text-[10px] font-black uppercase hover:bg-indigo-700 shadow-md active:scale-95 animate-bounce"><Camera className="h-3.5 w-3.5" /> Scan Gate QR</button>
                )}
              </div>
              <div className="space-y-4">
                {activePassesToday.map(p => {
                  const status = getScanStatus(p.session);
                  return (
                    <div key={p.id} className={`p-4 border-2 rounded-2xl transition-all ${status.open ? 'bg-indigo-50 border-indigo-100 shadow-sm' : 'bg-slate-50 border-slate-100 opacity-60'}`}>
                      <div className="flex justify-between items-center mb-2">
                        <div className="flex items-center gap-1.5">
                           {p.session === 'MORNING' ? <Sun className="h-3 w-3 text-amber-500" /> : p.session === 'EVENING' ? <Moon className="h-3 w-3 text-indigo-400" /> : <Maximize className="h-3 w-3 text-indigo-500" />}
                           <span className="text-[10px] font-black uppercase text-indigo-600 tracking-widest">{p.session}</span>
                        </div>
                        {status.open ? (
                          <span className="text-[9px] font-black text-indigo-600 bg-white px-2 py-0.5 rounded shadow-xs uppercase">Open</span>
                        ) : (
                          <span className="text-[9px] font-black text-slate-400 bg-white px-2 py-0.5 rounded shadow-xs uppercase">Closed</span>
                        )}
                      </div>
                      <p className="font-bold text-slate-800 text-sm mb-3 leading-tight">{hospitals.find(h => h.id === p.hospitalId)?.name}</p>

                      <div className="space-y-2 mb-4">
                        <div className="flex justify-between items-center text-[9px] font-black uppercase text-slate-400 tracking-tighter bg-white/50 p-1.5 rounded-lg border border-slate-100">
                          <span>Scanning Window</span>
                          <span className="text-indigo-600 font-black">{status.range}</span>
                        </div>
                        <div className="flex justify-between items-center text-[9px] font-black uppercase text-slate-400 tracking-tighter bg-white/50 p-1.5 rounded-lg border border-slate-100">
                          <span>Expiry Time</span>
                          <span className="text-red-500 font-black">{getExpiryTimeLabel(p.session)}</span>
                        </div>
                      </div>

                      {!status.open && (
                         <div className="flex items-center gap-2 mb-4 p-2 bg-amber-50 rounded-lg border border-amber-100">
                            <AlertTriangle className="h-3 w-3 text-amber-500 shrink-0" />
                            <p className="text-[10px] font-bold text-amber-700">{status.message}</p>
                         </div>
                      )}

                      <div className="bg-white p-3 rounded-xl border border-indigo-100 flex justify-between items-center"><div className="text-[9px] font-black text-slate-400 uppercase">Slot</div><div className="text-xs font-black text-slate-700">{p.timeSlot}</div></div>
                    </div>
                  );
                })}
                {activePassesToday.length === 0 && (
                   <div className="text-center py-10 text-slate-400 border-2 border-dashed border-slate-100 rounded-2xl">
                     <p className="text-xs font-bold italic opacity-40">No pending entry passes.</p>
                   </div>
                )}
              </div>
            </div>
          </section>
        </div>
      )}

      {activeTab === 'directory' && (
        <section className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 animate-in fade-in duration-300">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
            <h3 className="text-lg font-bold flex items-center gap-2"><Search className="h-5 w-5 text-indigo-500" /> Hospital Directory</h3>
            <div className="relative max-w-md w-full">
              <input type="text" placeholder="Search facilities..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all font-medium" />
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
            </div>
          </div>
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
             {hospitals.filter(h => h.isActive && h.name.toLowerCase().includes(searchTerm.toLowerCase())).map(h => {
               const approval = approvals.find(a => a.mrId === user.id && a.hospitalId === h.id);
               return (
                 <div key={h.id} className="p-6 bg-slate-50 border border-slate-100 rounded-3xl hover:border-indigo-200 transition-all flex flex-col justify-between">
                    <div>
                       <h4 className="font-bold text-slate-800 mb-1">{h.name}</h4>
                       <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tight flex items-center gap-1 mb-4"><MapPin className="h-3 w-3" /> {h.address || 'Colombo, Sri Lanka'}</p>
                    </div>
                    {approval ? (
                      <div className={`text-center py-2.5 rounded-xl text-xs font-black uppercase border ${approval.status === 'approved' ? 'bg-green-50 text-green-600 border-green-100' : 'bg-amber-50 text-amber-600 border-amber-100'}`}>
                        {approval.status === 'approved' ? 'Access Authorized' : 'Pending Approval'}
                      </div>
                    ) : (
                      <button onClick={async () => {
                        const newApprv: MRHospitalApproval = { id: 'apprv-'+Date.now(), mrId: user.id, hospitalId: h.id, status: 'pending', updatedAt: new Date().toISOString() };
                        const currentApprovals = await storageService.getApprovals();
                        await storageService.saveApprovals([...currentApprovals, newApprv]);
                        refreshData();
                        showFeedback("Access request sent to hospital admin.");
                      }} className="w-full py-2.5 bg-white border border-indigo-200 text-indigo-600 font-black rounded-xl text-xs hover:bg-indigo-600 hover:text-white transition-all shadow-sm">REQUEST ACCESS</button>
                    )}
                 </div>
               );
             })}
          </div>
        </section>
      )}

      {activeTab === 'profile' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm animate-in slide-in-from-bottom-4 duration-500 max-w-2xl mx-auto">
          <div className="flex flex-col items-center mb-8">
            <div className="w-24 h-24 bg-indigo-100 rounded-full flex items-center justify-center mb-4 border-4 border-white shadow-lg"><UserCircle className="h-12 w-12 text-indigo-600" /></div>
            <h3 className="text-2xl font-black text-slate-800">{user.fullName}</h3>
            <p className="text-indigo-600 font-bold uppercase tracking-widest text-xs mt-1">{user.companyName}</p>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Login ID</label><p className="font-bold text-slate-700 font-mono">{user.loginId}</p></div>
            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Mobile Access</label><p className="font-bold text-slate-700">{user.mobileNumber}</p></div>
            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Official MR ID</label><p className="font-bold text-slate-700 font-mono">{user.mrId}</p></div>
            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Compliance Badge</label><p className="font-bold text-indigo-600">Verified</p></div>
          </div>
        </section>
      )}

      {isScanning && <QRScannerModal onClose={() => setIsScanning(false)} onScan={handleScanDetected} mrId={user.id} />}
    </div>
  );
};

export default MRDashboard;

import React, { useState, useEffect, useContext, useCallback } from 'react';
import { 
  Play, Sparkles, CheckCircle, Clock, UserPlus, Users, Settings, Save, X, 
  Sun, Moon, Maximize, User, MapPin, ShieldCheck, 
  Mail, Phone, Briefcase, CheckCircle2, Eye, 
  Zap, Timer, HelpCircle, EyeOff, AlertTriangle, History, Search, Filter, Calendar, ChevronRight, ExternalLink
} from 'lucide-react';
import { storageService } from '../services/storageService';
import { lotteryService } from '../services/lotteryService';
import { MedicalRep, Hospital, PassApplication, IssuedPass, MRHospitalApproval, SessionType, PharmaCompany, EntryLog } from '../types';
import { getAdminBriefing } from '../services/pythonAIService';
import { FeedbackContext } from '../App';

interface AdminDashboardProps {
  user: {
    id: string;
    role: string;
    fullName: string;
    hospitalId: string;
  };
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [companies, setCompanies] = useState<PharmaCompany[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [logs, setLogs] = useState<EntryLog[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [activeTab, setActiveTab] = useState<'lottery' | 'history' | 'approvals' | 'companies' | 'settings'>('lottery');
  const [settingsTab, setSettingsTab] = useState<'profile' | 'sessions'>('profile');
  const [brief, setBrief] = useState('');
  const [selectedMR, setSelectedMR] = useState<MedicalRep | null>(null);
  const [showHowItWorks, setShowHowItWorks] = useState(false);
  const [historySearch, setHistorySearch] = useState('');
  const [historySessionFilter, setHistorySessionFilter] = useState<SessionType | 'ALL'>('ALL');
  const [selectedCompanyId, setSelectedCompanyId] = useState<string | null>(null);
  const [editingHospital, setEditingHospital] = useState<Hospital | null>(null);

  const refreshData = useCallback(async () => {
    const allHospitals = await storageService.getHospitals();
    const currentHosp = allHospitals.find(h => h.id === user.hospitalId);

    setHospitals(allHospitals);
    setMrs(await storageService.getMRs()); 
    setCompanies(await storageService.getCompanies());
    const allApps = await storageService.getApplications();
    setApps(allApps); 
    const allPasses = await storageService.getPasses();
    setPasses(allPasses);
    setLogs(await storageService.getLogs());
    setApprovals(await storageService.getApprovals());

    if (currentHosp && !editingHospital) {
      setEditingHospital({
        ...currentHosp,
        autoLotteryEnabled: currentHosp.autoLotteryEnabled || {},
        autoLotteryTimes: currentHosp.autoLotteryTimes || {},
        passLimits: currentHosp.passLimits || {},
        sessionWindows: currentHosp.sessionWindows || {},
        supportedSessions: currentHosp.supportedSessions || []
      });
    }

    try {
      // Calling Python AI Service instead of Gemini
      const summary = await getAdminBriefing(
        allApps, 
        allPasses,
        currentHosp?.name || 'Hospital'
      );
      setBrief(summary);
    } catch (e) {
      console.error("Briefing failed", e);
    }
  }, [user.hospitalId, editingHospital]);

  useEffect(() => { 
    refreshData(); 
    const interval = setInterval(refreshData, 30000);
    return () => clearInterval(interval);
  }, [refreshData]);

  const handleManualLottery = async (session: SessionType) => {
    const result = await lotteryService.runLottery(user.hospitalId, session);
    if (result.success) {
      showFeedback(result.message, 'success');
      refreshData();
    } else {
      showFeedback(result.message, 'error');
    }
  };

  const handleSaveHospitalData = async () => {
    if (!editingHospital) return;
    const allHospitals = await storageService.getHospitals();
    const updated = allHospitals.map(h => h.id === editingHospital.id ? editingHospital : h);
    await storageService.saveHospitals(updated);
