                  </div>
                </div>
              </div>
            ) : (
              <div className="space-y-6">
                {(['MORNING', 'EVENING', 'FULL_DAY'] as SessionType[]).map(sess => {
                  const isSupported = editingHospital.supportedSessions.includes(sess);
                  const isAuto = editingHospital.autoLotteryEnabled?.[sess] || false;

                  return (
                    <div key={sess} className={`p-6 rounded-3xl border-2 transition-all ${isSupported ? 'bg-white border-indigo-100 shadow-sm' : 'bg-slate-50 border-dashed border-slate-200 opacity-60'}`}>
                        <div className="flex items-center justify-between mb-4">
                          <div className="flex items-center gap-2">
                             {sess === 'MORNING' ? <Sun className="h-5 w-5 text-amber-500" /> : sess === 'EVENING' ? <Moon className="h-5 w-5 text-indigo-500" /> : <Maximize className="h-5 w-5 text-indigo-600" />}
                             <span className="font-black text-slate-800 uppercase tracking-widest">{sess.replace('_', ' ')}</span>
                          </div>
                          <label className="relative inline-flex items-center cursor-pointer">
                              <input type="checkbox" checked={isSupported} onChange={() => toggleSupportedSession(sess)} className="sr-only peer" />
                              <div className="w-11 h-6 bg-gray-200 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-indigo-600"></div>
                          </label>
                        </div>

                        {isSupported && (
                          <div className="space-y-4">
                             <div className="grid grid-cols-2 gap-4">
                                <div>
                                   <label className="text-[10px] font-black text-slate-400 uppercase mb-1 block">Pass Limit</label>
                                   <input 
                                     type="number" 
                                     value={editingHospital.passLimits?.[sess] || 0}
                                     onChange={(e) => updateSessionSetting(sess, 'passLimits', parseInt(e.target.value) || 0)}
                                     className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl font-bold" 
                                   />
                                </div>
                             </div>
                          </div>
                        )}
                    </div>
                  );
                })}
              </div>
            )}

            <div className="pt-6 border-t border-slate-100">
               <button onClick={handleSaveHospitalData} className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-xl hover:bg-indigo-700 active:scale-95 transition-all flex items-center justify-center gap-2">
                 <Save className="h-5 w-5" /> COMMIT SYSTEM CHANGES
               </button>
            </div>
          </div>
        </section>
      )}

      {selectedMR && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-lg rounded-3xl shadow-2xl overflow-hidden p-8">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold">Representative Identity</h3>
              <button onClick={() => setSelectedMR(null)}><X className="h-5 w-5 text-slate-400" /></button>
            </div>
            <div className="space-y-6 text-center">
              <div className="w-20 h-20 bg-indigo-100 rounded-full flex items-center justify-center mx-auto mb-4 border-4 border-white shadow-sm">
                <User className="h-10 w-10 text-indigo-600" />
              </div>
              <h4 className="text-2xl font-black text-slate-800">{selectedMR.fullName}</h4>
              <p className="text-indigo-600 font-bold text-sm tracking-wide uppercase">{selectedMR.companyName}</p>
              <button onClick={() => setSelectedMR(null)} className="w-full bg-slate-800 text-white font-black py-4 rounded-2xl shadow-xl hover:bg-slate-900 transition-all uppercase tracking-widest text-xs">CLOSE PROFILE</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;
